class Shape2D(ABC):
    @abstractmethod
    def area(self):
        pass

class Shape3D(ABC):
    @abstractmethod
    def volume(self):
        pass

class Calculator(ABC):
    def __init__(self, shapes=[]) -> None:
        self.shapes = shapes
    
    @abstractmethod
    def sum(self):
        pass

class AreaCalculator(Calculator):
    def sum(self):
        total_area = 0
        for shape in self.shapes:
            if isinstance(shape, Shape2D):
                total_area += shape.area()
            else:
                raise Exception("Invalid Shape: Shape does not implement Shape2D interface")
        return total_area

class VolumeCalculator(Calculator):
    def sum(self):
        total_volume = 0
        for shape in self.shapes:
            if isinstance(shape, Shape3D):
                total_volume += shape.volume()
            else:
                raise Exception("Invalid Shape: Shape does not implement Shape3D interface")
        return total_volume
